export const deformableDistanceContract=Object.freeze({components:['Cloth grid/rope','Rope2D'],fields:{pinWeights:'sparse [{index,weight}] 0..1 authored rest-pose drive; weight is position/velocity blend at60Hz, alpha=1-(1-weight)^(dt*60); absent/zero free, one fully follows rest center, never overrides hard pins/rigid attachments',motionLimits:'sparse [{index,radius}] world-unit sphere around authored local rest point transformed with current actor hierarchy; zero radius holds position',distanceTethers:'sparse [{index,anchor,distance}] maximum world-unit distance, unique unordered particle pairs; dynamic pair corrections weighted by inverse particle mass',distanceIterations:'1..64 post-step projection sweeps, default4; final maxError reports incompatible/unconverged constraints'},runtime:'Opt-in engine position projection after Rapier soft-body step, before published geometry/contact inspection; removes separating relative velocity. No whole-particle snapshots. Hard pins and actual rigid attachments have zero inverse mass and are never moved. Legacy empty arrays allocate no constraint owner/pass.',editing:'Hot typed component edits preserve generation, velocities, runtime pins, attachments and plastic rest state. Topology edits prune out-of-range rows. Weighted pin target velocity follows actor-center motion; one blend per fixed step before distance sweeps. Existing componentSetJson/hb::Components::SetText and existing Undo/save use identical validation.',limits:['Projection is not a Rapier internal contact/force constraint; contacts are solved on the next substep, no rigid-body reaction force from projected motion','Incompatible constraints can retain residual error; automatic nearest-anchor rows use the opt-in DeformableAutoTethers regular-grid/rope owner; weighted pins have typed index controls and the existing stroke/Undo/cancel painter','No self-collision/CCD guarantee or GPU/device performance claim']});
